def epoch_cap(available: int) -> int:
    return available * DECAY_NUM // DECAY_DEN


def available(vault_balance: int, pending: int, outstanding: int) -> int:
    a = vault_balance - pending - outstanding
    if a < 0:
        raise ValueError("reserve underflow: V < P + O")
    return a


def scaled(production_seconds: int, epoch_seconds: int = DAY) -> int:
    return production_seconds * epoch_seconds // DAY


def epoch_start(genesis_ts: int, epoch: int, epoch_seconds: int = DAY) -> int:
    return genesis_ts + epoch * epoch_seconds


def close_window(genesis_ts: int, epoch: int, epoch_seconds: int = DAY) -> tuple[int, int]:
    """[start + REVEAL_END, start + EPOCH + CLOSE_GRACE)"""

    s = epoch_start(genesis_ts, epoch, epoch_seconds)
