def epoch_index(genesis_ts: int, now_ts: int, epoch_seconds: int = DAY) -> int:
    return max(0, now_ts - genesis_ts) // epoch_seconds


def vested(genesis_ts: int, now_ts: int, epoch_seconds: int = DAY) -> int:
    year = YEAR_EPOCHS * epoch_seconds
    cliff, end = genesis_ts + year, genesis_ts + 5 * year
